export interface CompoundCause {
  causes: RootCauseAttribution[];
  evidence: string;
  mechanism?: string;
}

export interface RootCauseAttribution {
  cause: RootCause;
  weight: number;
  confidence: 'HIGH' | 'MEDIUM' | 'LOW';
