  return (
    (1 - risk.misalignmentRisk) * 0.35 +
    (1 - risk.safetyDebt) * 0.35 +
    (1 - risk.concentrationRisk) * 0.15 +
    (1 - risk.complacencyLevel) * 0.15
  );
}

