      console.log(`     Magnitude: ${cascadePotential.toFixed(2)} → +${(cascadeSize * 100).toFixed(1)}% mobilization`);
      console.log(`     Cascade type: Leipzig 1989 / Arab Spring mechanism (hidden dissent revealed)`);
    }
  }

  // === CRISIS TRIGGERS ===
  checkSocialCrises(state);
}

/**
