 * (Uses LOWEST confidence of all components)
 */
export function getCompoundConfidence(compound: CompoundCause): 'HIGH' | 'MEDIUM' | 'LOW' {
  const confidenceLevels = { 'HIGH': 3, 'MEDIUM': 2, 'LOW': 1 };

