  // Rich countries: inequality → climate (poverty not a factor)
  // Poor countries: climate → inequality (poverty dominates)
  if (inequalityWeight < 0.10 && inequalityWeight > 0) {
    climateWeight = climateWeight + inequalityWeight;
    inequalityWeight = 0;

