            console.log(`\n⚠️  MAJOR CRISIS COMPLETE: ${state.extinctionState.type?.toUpperCase()}`);
            console.log(`   Mechanism: ${state.extinctionState.mechanism}`);
            console.log(`   Duration: ${month - state.extinctionState.startMonth} months`);
            console.log(`   Population Remaining: ${population.toFixed(2)}B`);
            console.log(`   Status: HUMANITY SURVIVES (not extinct)\n`);
          }
        } else if (population >= 0.00001) {  // 10K-100M = bottleneck
          if (month - state.extinctionState.startMonth === 1) {
            console.log(`\n🚨 GENETIC BOTTLENECK: ${state.extinctionState.type?.toUpperCase()}`);
            console.log(`   Population: ${(population * 1_000_000_000).toFixed(0)} people`);
            console.log(`   Status: Critical but not extinct\n`);
          }
        }
      }

      // Phase: Golden Age & Accumulation Systems
      // Update Golden Age state each month (tracks entry/exit/duration)
      updateGoldenAgeState(state, month);

      // Phase 2: Environmental Accumulation
      // Track environmental debt from production/growth
      updateEnvironmentalAccumulation(state);

      // Phase 3: Social Cohesion & Meaning Crisis
      // Track psychological and social costs from automation
      updateSocialAccumulation(state);

      // Phase 4: Technological Risk Accumulation
      // Track AI safety debt and complacency
      updateTechnologicalRisk(state);

      // Phase 2A: Breakthrough Technologies
      // DISABLED: Now handled by TechTreePhase (Phase 12.5) in orchestrator
      // The old breakthroughTechnologies system was DOUBLE-APPLYING effects!
      // - Phase 12.5: TechTreePhase → applyAllTechEffects() [NEW SYSTEM]
      // - Line 558: updateBreakthroughTechnologies() → applyTechnologyEffects() [OLD SYSTEM]
      // Both modified same properties (biodiversity, climate, pollution, meaning, etc.)
      // Keeping the NEW system only, which has 70 tech with proper prereqs, costs, regional deployment

      // try {
      //   updateBreakthroughTechnologies(state, month);
      //   checkCrisisResolution(state, month);
      // } catch (error) {
      //   console.error(`\n❌ BREAKTHROUGH TECH ERROR: ${error}`);
      //   console.error(error);
      // }

      // Check for ACTUAL outcomes (not probabilities)
      if (checkActualOutcomes) {
        const outcomeCheck = determineActualOutcome(state, month);
        if (outcomeCheck.outcome !== 'active') {
          actualOutcome = outcomeCheck.outcome;
          actualOutcomeReason = outcomeCheck.reason;
          // Log why the game ended
          console.log(`\n🎮 Simulation ended: ${outcomeCheck.outcome.toUpperCase()}`);
          console.log(`   Reason: ${outcomeCheck.reason}`);
          console.log(`   Confidence: ${(outcomeCheck.confidence * 100).toFixed(0)}%`);
          console.log(`   Month: ${month}\n`);
          break;
        }
      }
    }

    // Log if reached max months without definitive outcome
    if (!actualOutcome) {
      console.log(`\n⏱️  SIMULATION REACHED MAX DURATION: ${maxMonths} months (${(maxMonths/12).toFixed(1)} years)`);
      console.log(`   No definitive outcome - determining based on final probabilities`);
    }

    // Determine final outcome (TIER 1.7: Fixed to use actual population, not probability)
    const finalMetrics = history[history.length - 1].metrics;
    const outcomes = finalMetrics.outcomeProbs;
    const finalPopulation = state.humanPopulationSystem.population;
    const finalPopulationPeople = finalPopulation * 1_000_000_000;

    let finalOutcome: 'utopia' | 'dystopia' | 'extinction' | 'inconclusive';
    let finalOutcomeProbability: number;

    // If we found an actual outcome during simulation, use that
    if (actualOutcome) {
      finalOutcome = actualOutcome;
      // Use the corresponding probability
      if (actualOutcome === 'utopia') finalOutcomeProbability = outcomes.utopiaProbability;
      else if (actualOutcome === 'dystopia') finalOutcomeProbability = outcomes.dystopiaProbability;
      else finalOutcomeProbability = outcomes.extinctionProbability;
    } 
    // Otherwise, determine outcome based on ACTUAL STATE, not just probabilities
    else {
      console.log(`   📊 Final probabilities: Utopia ${(outcomes.utopiaProbability*100).toFixed(1)}%, Dystopia ${(outcomes.dystopiaProbability*100).toFixed(1)}%, Extinction ${(outcomes.extinctionProbability*100).toFixed(1)}%`);
      console.log(`   👥 Final population: ${finalPopulation.toFixed(2)}B (${finalPopulationPeople.toFixed(0)} people)`);

      // NEW (Oct 13, 2025): 7-tier outcome classification system
      // Replaces binary extinction with nuanced severity levels
      const classifiedOutcome = classifyPopulationOutcome(finalPopulation, savedInitialPopulation, state);

      // P1.4 FIX: Map 7-tier classification to 4 final outcomes
      // Only TRUE extinction (<10K people) should report as 'extinction'
      // All other severe outcomes (terminal, bottleneck, collapse, etc.) are 'dystopia'
      if (classifiedOutcome === 'extinction') {
        // TRUE EXTINCTION: <10K people (not 1B-4B survivors!)
        finalOutcome = 'extinction';
        finalOutcomeProbability = 1.0;
        console.log(`   💀 TRUE EXTINCTION confirmed (<10K people)\n`);
      } else if (classifiedOutcome !== 'status_quo') {
        // Population-based DYSTOPIA (terminal, bottleneck, dark_age, collapse, crisis_era)
        // These are severe outcomes but humanity survives (100M-7B people)
        finalOutcome = 'dystopia';
        finalOutcomeProbability = 1.0;
        console.log(`   🏛️  DYSTOPIA (${classifiedOutcome.toUpperCase()}) - humanity survives with ${finalPopulation.toFixed(2)}B people\n`);
      } else if (outcomes.utopiaProbability > 0.45 && outcomes.utopiaProbability > outcomes.dystopiaProbability * 1.2) {
        // Clear Utopia trajectory (TIER 0A FIX: lowered from 0.6 + 1.5x to 0.45 + 1.2x)
        finalOutcome = 'utopia';
        finalOutcomeProbability = outcomes.utopiaProbability;
        console.log(`   🌟 UTOPIA trajectory dominant (${(outcomes.utopiaProbability*100).toFixed(1)}% vs dystopia ${(outcomes.dystopiaProbability*100).toFixed(1)}%)\n`);
      } else if (outcomes.dystopiaProbability > 0.45 && outcomes.dystopiaProbability > outcomes.utopiaProbability * 1.2) {
        // Clear Dystopia trajectory (TIER 0A FIX: lowered from 0.6 + 1.5x to 0.45 + 1.2x)
        finalOutcome = 'dystopia';
        finalOutcomeProbability = outcomes.dystopiaProbability;
        console.log(`   🏛️  DYSTOPIA trajectory dominant (${(outcomes.dystopiaProbability*100).toFixed(1)}% vs utopia ${(outcomes.utopiaProbability*100).toFixed(1)}%)\n`);
      } else if (outcomes.extinctionProbability > 0.40) {
        // Extinction is clearly dominant (TIER 0A FIX: new branch for high extinction probability)
        finalOutcome = 'extinction';
        finalOutcomeProbability = outcomes.extinctionProbability;
        console.log(`   💀 EXTINCTION probability dominant (${(outcomes.extinctionProbability*100).toFixed(1)}%)\n`);
      } else if (outcomes.utopiaProbability > outcomes.dystopiaProbability && outcomes.utopiaProbability > outcomes.extinctionProbability) {
        // Utopia is leading (even if not by much) (TIER 0A FIX: new fallback for utopia)
        finalOutcome = 'utopia';
        finalOutcomeProbability = outcomes.utopiaProbability;
        console.log(`   🌟 UTOPIA trajectory leading (${(outcomes.utopiaProbability*100).toFixed(1)}% > ${(outcomes.dystopiaProbability*100).toFixed(1)}% dystopia, ${(outcomes.extinctionProbability*100).toFixed(1)}% extinction)\n`);
      } else if (outcomes.dystopiaProbability > outcomes.utopiaProbability && outcomes.dystopiaProbability > outcomes.extinctionProbability) {
        // Dystopia is leading (TIER 0A FIX: new fallback for dystopia)
        finalOutcome = 'dystopia';
        finalOutcomeProbability = outcomes.dystopiaProbability;
        console.log(`   🏛️  DYSTOPIA trajectory leading (${(outcomes.dystopiaProbability*100).toFixed(1)}% > ${(outcomes.utopiaProbability*100).toFixed(1)}% utopia, ${(outcomes.extinctionProbability*100).toFixed(1)}% extinction)\n`);
      } else {
        // True mixed signals - very rare now (TIER 0A FIX: only when all probabilities within 0.05 of each other)
        finalOutcome = 'inconclusive';
        finalOutcomeProbability = Math.max(
          outcomes.utopiaProbability,
          outcomes.dystopiaProbability,
          outcomes.extinctionProbability
        );
        console.log(`   ❓ INCONCLUSIVE - truly mixed signals (utopia ${(outcomes.utopiaProbability*100).toFixed(1)}%, dystopia ${(outcomes.dystopiaProbability*100).toFixed(1)}%, extinction ${(outcomes.extinctionProbability*100).toFixed(1)}%)\n`);
      }
    }

    // Phase 1B Refinement (Oct 17, 2025): Stratified Outcome Classification
    // Distinguish humane (prosperity without mass death) vs pyrrhic (recovery after catastrophe) outcomes
    const initialPopulation = savedInitialPopulation || 8.0; // Use saved value from simulation start
    const stratificationResult = classifyStratifiedOutcome(state, finalOutcome, initialPopulation);

    // Store in state for analysis
    state.stratifiedOutcome = stratificationResult.stratifiedOutcome;
    state.mortalityBand = stratificationResult.mortalityBand;
    state.initialPopulation = initialPopulation;

    // Log stratified classification
    const mortalityRate = 1 - (finalPopulation / initialPopulation);
    console.log(`\n📊 STRATIFIED OUTCOME CLASSIFICATION:`);
    console.log(`   Base Outcome: ${finalOutcome.toUpperCase()}`);
    console.log(`   Stratified Outcome: ${stratificationResult.stratifiedOutcome.toUpperCase()}`);
    console.log(`   Mortality Band: ${stratificationResult.mortalityBand.toUpperCase()} (${(mortalityRate * 100).toFixed(1)}% mortality)`);
    console.log(`   Population: ${initialPopulation.toFixed(2)}B → ${finalPopulation.toFixed(2)}B`);

    // Log interpretation
    if (stratificationResult.stratifiedOutcome === 'humane-utopia') {
      console.log(`   ✅ HUMANE UTOPIA: Prosperity achieved WITHOUT mass death`);
    } else if (stratificationResult.stratifiedOutcome === 'pyrrhic-utopia') {
      console.log(`   ⚔️  PYRRHIC UTOPIA: Recovery AFTER catastrophe (${(mortalityRate * 100).toFixed(1)}% mortality = ${((initialPopulation - finalPopulation) * 1000).toFixed(0)}M deaths)`);
    } else if (stratificationResult.stratifiedOutcome === 'humane-dystopia') {
      console.log(`   🏛️  HUMANE DYSTOPIA: Oppression WITHOUT mass death`);
    } else if (stratificationResult.stratifiedOutcome === 'pyrrhic-dystopia') {
      console.log(`   ⚰️  PYRRHIC DYSTOPIA: Oppression AFTER catastrophe (${(mortalityRate * 100).toFixed(1)}% mortality = ${((initialPopulation - finalPopulation) * 1000).toFixed(0)}M deaths)`);
    } else if (stratificationResult.stratifiedOutcome === 'bottleneck') {
      console.log(`   🧬 BOTTLENECK: Near-extinction recovery (<500M population)`);
    }
    console.log(``);

    // Log final population outcome (TIER 1.5)
    const { determinePopulationOutcome, logDeathSummary } = require('./populationDynamics');
    const { logRegionalPopulationSummary } = require('./regionalPopulations');

    const finalPopOutcome = determinePopulationOutcome(state);
    console.log(`\n👥 FINAL POPULATION STATUS:`);
    console.log(`   Status: ${finalPopOutcome.status.toUpperCase()}`);
    console.log(`   Final Population: ${finalPopOutcome.finalPopulation.toFixed(2)}B`);
    console.log(`   Peak Population: ${finalPopOutcome.peakPopulation.toFixed(2)}B`);
    console.log(`   Decline: ${finalPopOutcome.populationDecline.toFixed(1)}%`);
    console.log(`   ${finalPopOutcome.outcomeNarrative}\n`);

    // Log death summary statistics (TIER 1.5)
    logDeathSummary(state);

    // Log regional population breakdown (TIER 1.5 - Phase 5)
    logRegionalPopulationSummary(state);

    // Finalize log
    const log = logger.finalize(state, finalOutcome);
    const diagnostics = diagnosticLogger.finalize(state, finalOutcome);

    // Print diagnostic report if verbose
    if (process.env.VERBOSE_DIAGNOSTICS === 'true') {
      console.log(formatDiagnosticReport(diagnostics));
    }

    return {
      finalState: state,
      history,
      log,
      diagnostics,
      summary: {
        totalMonths: history.length,
        finalOutcome,
        finalOutcomeReason: actualOutcomeReason || `Reached max months (${maxMonths}) with ${finalOutcome} probability dominant`,
        finalOutcomeProbability,
        criticalEvents: log.events.criticalEvents,
        economicStageReached: state.globalMetrics.economicTransitionStage
      }
    };
  }

  /**
   * Get current random number generator (useful for testing)
   */
  getRNG(): SeededRandom {
    return this.rng;
  }
}

/**
 * Create a default initial state for simulations
 */
export function createDefaultInitialState(): GameState {
  // This would import from gameStore's createInitialState
  // For now, return a minimal valid state
  // TODO: Import actual initial state creation logic
  return {} as GameState; // Placeholder
}

